/*
 * The Button Function entries (sdk/lib/fnfunc_em10ii.c) in the GDB simulator, on the stock image's
 * bytes of every table the library checks or copies (copied to their run addresses from
 * sim_image[], generated by tests/test_sim.py from the firmware BIN), with the event layer and the
 * E-M10 II hook runtime posting through the patched appevent_post entry onto the recording mock
 * ./fw.S, and ../hooks_em10ii/sim_start.S. The firmware side is modelled from its listing: the
 * store record's list (count = bytes / width), the label lookup by value of the selector and the
 * row cell, the property registry under the settings map. plugin_main sets sim_exit_code to 0 or
 * the number of the first failed check.
 */
#include <fenykl.h>
#include <event.h>
#include <fnfunc.h>

#define CHECK(n, cond)					\
	do {						\
		if (!(cond) && !sim.first_fail)		\
			sim.first_fail = (n);		\
	} while (0)

#define GUI_SM ((volatile uint8_t *)0x619A3740u)
#define LIVE 0x0108u
#define MENU 0x1102u
#define PRESS(c) (FENYKL_EVENT_KEY_PRESS | (c))
#define RELEASE(c) (FENYKL_EVENT_KEY_RELEASE | (c))

#define ID 0x3BFu
#define OFF 0x7D0u
#define PROP_BUTTONS 0xECC2u	/* u16 [5]: Fn1, REC, Fn2, -, Fn3 */
#define PROP_LFN 0xECE2u	/* u16: L-Fn */
#define PROP_MODE 0xE1E1u	/* u8: setting 0x217 */
#define WORDS 80u
#define KEYS 15u
#define KEY_STRIDE 0x1Cu
#define NAMES_N 37u
#define HELP_N 37u
#define CELLS_N 38u
#define ROW(r) (FW_BUTTON_ROWS + 0x24u * (r))

struct sim_region {
	uint32_t addr, len;
	const uint8_t *bytes;
};

struct post {
	uint32_t event, param, flag;
};

struct sim_button {
	uint32_t rec;
	unsigned int n, row;
	uint16_t setting, code;
};

extern const struct sim_region sim_image[];
extern const unsigned int sim_image_n;

struct sim_state {
	uint32_t first_fail;
	unsigned int flushes, yields, window_bad;
	bool watch;			/* judge the tables at every flush and yield */
	unsigned int corrupt_at;	/* flush number at which a row count changes, 0 never */
	uint16_t buttons[5], lfn;
	uint8_t mode;
	uint32_t nodes[5][2];		/* the record hash's nodes {record, next} */
	unsigned int presses;
	enum fenykl_fnfunc_button last;
};

static struct sim_state sim;

struct post sim_posts[64];		/* ./fw.S appends here */
uint32_t sim_nposts;
uint32_t sim_exit_code = 99;

/* in table order of enum fenykl_fnfunc_button */
static const struct sim_button sim_buttons[FENYKL_FNFUNC_BUTTONS] = {
	{ FW_SETTING_REC_FN1, 28, 0, 0x2F, 0x000B },
	{ FW_SETTING_REC_FN2, 28, 1, 0x31, 0x1209 },
	{ FW_SETTING_REC_FN3, 28, 3, 0x23B, 0x1224 },
	{ FW_SETTING_REC_REC, 28, 2, 0x30, 0x120A },
	{ FW_SETTING_REC_LFN, 29, 7, 0x38, 0x2202 },
};

static const char name[] = "Screenshot";
static const char help[] = "(Fenykl) Saves screen to card";

static uint32_t rd32(uint32_t a)
{
	return *(volatile uint32_t *)a;
}

static uint32_t rd16(uint32_t a)
{
	return *(volatile uint16_t *)a;
}

static void wr32(uint32_t a, uint32_t v)
{
	*(volatile uint32_t *)a = v;
}

static void wr16(uint32_t a, uint32_t v)
{
	*(volatile uint16_t *)a = (uint16_t)v;
}

static void on_press(enum fenykl_fnfunc_button b, void *arg)
{
	(void)arg;
	sim.presses++;
	sim.last = b;
}

static const struct fenykl_fnfunc func = { .name = name, .help = help, .press = on_press };

static bool sim_tables_consistent(void);

/* --- mocks (fw.S forwards here) --- */

uint32_t c_OlyTaskSleep(void)
{
	if (sim.watch) {
		sim.yields++;
		if (!sim_tables_consistent())
			sim.window_bad++;
	}
	return 0;
}

uint32_t c_dcache_flush_all(void)
{
	if (!sim.watch)
		return 0;
	sim.flushes++;
	if (!sim_tables_consistent())
		sim.window_bad++;
	if (sim.flushes == sim.corrupt_at)
		wr32(ROW(0) + 16u, 0x30);
	return 0;
}

/* --- the firmware model --- */

static void sim_prop(unsigned int id, void *obj)
{
	wr32(FW_PROP_TABLE + 8u * (id >> 4) + 4u, (uint32_t)obj);
}

static unsigned int rec_count(uint32_t rec)
{
	uint32_t w = rd32(rec + 12u);

	return (w & 0xFFFFu) / (w >> 16);
}

static uint32_t rec_value(uint32_t rec, unsigned int i)
{
	return rd16(rd32(rec + 4u) + 2u * i);
}

/* The label lookup by value: kind, and the text for kind 5; 0 if the value is not in the table. */
static uint32_t fw_label(uint32_t table, unsigned int n, uint32_t value, const char **text)
{
	for (unsigned int i = 0; i < n; i++) {
		uint32_t e = table + 12u * i;

		if (rd32(e) != value)
			continue;
		*text = (const char *)rd32(e + 8u);
		return rd16(e + 4u);
	}
	return 0;
}

/* Key entry k's names (help: true, its help) lookup of value. */
static uint32_t fw_selector(unsigned int k, bool help, uint32_t value, const char **text)
{
	uint32_t e = FW_FUNC_SELECTOR_KEYS + KEY_STRIDE * k;

	return fw_label(rd32(e + (help ? 20u : 12u)), rd16(e + (help ? 6u : 2u)), value, text);
}

static uint32_t fw_cell(unsigned int row, uint32_t value, const char **text)
{
	return fw_label(rd32(ROW(row) + 12u), rd32(ROW(row) + 16u), value, text);
}

/* Every stock pointer has its stock count (the corrupted row count aside). */
static bool sim_tables_consistent(void)
{
	for (unsigned int k = 0; k < KEYS; k++) {
		uint32_t e = FW_FUNC_SELECTOR_KEYS + KEY_STRIDE * k;

		if (rd32(e + 12u) == FW_FUNC_NAMES && rd16(e + 2u) != NAMES_N)
			return false;
		if (rd32(e + 20u) == FW_FUNC_HELP && rd16(e + 6u) != HELP_N)
			return false;
	}
	for (unsigned int i = 0; i < FENYKL_FNFUNC_BUTTONS; i++) {
		const struct sim_button *b = &sim_buttons[i];
		uint32_t row = ROW(b->row);

		if (rd32(row + 12u) == FW_BUTTON_CELLS && rd32(row + 16u) != CELLS_N &&
		    rd32(row + 16u) != 0x30)
			return false;
		if ((rd32(b->rec + 4u) & 0xF0000000u) != 0xA0000000u && rec_count(b->rec) != b->n)
			return false;
	}
	return true;
}

/* --- setup --- */

static void sim_stock(void)
{
	for (unsigned int i = 0; i < sim_image_n; i++)
		memcpy((void *)sim_image[i].addr, sim_image[i].bytes, sim_image[i].len);
}

static bool sim_is_stock(void)
{
	for (unsigned int i = 0; i < sim_image_n; i++)
		if (memcmp((const void *)sim_image[i].addr, sim_image[i].bytes, sim_image[i].len))
			return false;
	return true;
}

static void set_gui(uint16_t gui)
{
	GUI_SM[0] = gui >> 8;
	GUI_SM[1] = gui & 0xFF;
}

/* The boot-built record lookup, the props, sections 2..4 loaded, live view. */
static void sim_setup(void)
{
	for (unsigned int i = 0; i < FENYKL_FNFUNC_BUTTONS; i++) {
		const struct sim_button *b = &sim_buttons[i];

		sim.nodes[i][0] = b->rec;
		wr32(FW_SETTING_REC_HASH + 4u * (b->setting & 0x7Fu), (uint32_t)sim.nodes[i]);
	}
	sim.buttons[0] = 0x8DC;
	sim.buttons[1] = 0x2C;
	sim.buttons[2] = 0x1B5;
	sim.buttons[4] = 0x3B1C;
	sim.lfn = 0x7D9;
	sim.mode = 1;
	sim_prop(PROP_BUTTONS, sim.buttons);
	sim_prop(PROP_LFN, &sim.lfn);
	sim_prop(PROP_MODE, &sim.mode);
	*(volatile uint8_t *)FW_SECTION_LOADED = 0x0E;
	set_gui(LIVE);
}

/* A kind-5 label with the text want, NUL included. */
static bool sim_text(uint32_t kind, const char *text, const char *want)
{
	unsigned int i = 0;

	if (kind != 5 || !text)
		return false;
	while (want[i] && text[i] == want[i])
		i++;
	return text[i] == want[i];
}

/* Posts through the patched entry; true if it reached the firmware and nothing else did. */
static bool post(uint32_t event)
{
	uint32_t n = sim_nposts;

	return fw_appevent_post(event, 0, 0) == 1 && sim_nposts == n + 1 &&
	       sim_posts[n].event == event;
}

/* event passed, with (callback b) or without (callback none) a press callback */
static bool pressed(uint32_t event, int b)
{
	unsigned int n = sim.presses;

	if (!post(event))
		return false;
	if (b < 0)
		return sim.presses == n;
	return sim.presses == n + 1 && sim.last == (enum fenykl_fnfunc_button)b;
}

/* --- checks --- */

static void check_refusals(void)
{
	static const struct fenykl_fnfunc long_name = {
		.name = "(Fenykl) A name of 33 characters.", .help = "h", .press = on_press,
	};
	static const struct fenykl_fnfunc no_press = { .name = "n", .help = "h" };
	static const struct fenykl_fnfunc max_name = {
		.name = "(Fenykl) A name of 32 characters", .help = "", .press = on_press,
	};

	sim_stock();
	sim_setup();
	CHECK(1, fenykl_fnfunc_install(&long_name) == FENYKL_FNFUNC_EARG &&
		 fenykl_fnfunc_install(&no_press) == FENYKL_FNFUNC_EARG &&
		 fenykl_fnfunc_install(&max_name) == FENYKL_FNFUNC_EARG && sim_is_stock());
	*(volatile uint8_t *)FW_SECTION_LOADED = 0x06;
	CHECK(2, fenykl_fnfunc_install(&func) == FENYKL_FNFUNC_EAGAIN);
	*(volatile uint8_t *)FW_SECTION_LOADED = 0x0E;
	set_gui(MENU);
	CHECK(3, fenykl_fnfunc_install(&func) == FENYKL_FNFUNC_EAGAIN && sim_is_stock());
	set_gui(LIVE);
	/* L-Fn's picker init entry */
	wr32(FW_BUTTON_PICKER_INIT + 8u * 10u + 4u, 0x609EE410u);
	CHECK(4, fenykl_fnfunc_install(&func) == FENYKL_FNFUNC_ESTOCK);
	sim_stock();
	/* a count override on Fn2, a moved record, a changed map entry, a key entry, Fn3's list
	   differing from Fn1's, a label for 0x3BF */
	wr16(FW_SETTING_COUNT_SLOTS + 0x4Cu + 0x44u, 0x31);
	CHECK(5, fenykl_fnfunc_install(&func) == FENYKL_FNFUNC_ESTOCK);
	wr16(FW_SETTING_COUNT_SLOTS + 0x4Cu + 0x44u, 0);
	sim.nodes[3][0] = FW_SETTING_REC_REC + 0x14u;
	CHECK(6, fenykl_fnfunc_install(&func) == FENYKL_FNFUNC_ESTOCK);
	sim.nodes[3][0] = FW_SETTING_REC_REC;
	wr32(FW_SETTING_MAP + 4u * 0x38u, 0xECE3u);
	CHECK(7, fenykl_fnfunc_install(&func) == FENYKL_FNFUNC_ESTOCK);
	sim_stock();
	wr32(FW_FUNC_SELECTOR_KEYS + KEY_STRIDE * 7u + 20u, FW_FUNC_NAMES);
	CHECK(8, fenykl_fnfunc_install(&func) == FENYKL_FNFUNC_ESTOCK);
	sim_stock();
	wr16(rd32(FW_SETTING_REC_FN3 + 4u) + 2u * 5u, 0x22);
	CHECK(9, fenykl_fnfunc_install(&func) == FENYKL_FNFUNC_ESTOCK);
	sim_stock();
	wr32(FW_BUTTON_CELLS + 12u * 10u, ID);
	CHECK(10, fenykl_fnfunc_install(&func) == FENYKL_FNFUNC_ESTOCK);
	sim_stock();
	/* the first row count changes during the install: rolled back to the stock words */
	sim.watch = true;
	sim.flushes = 0;
	sim.corrupt_at = 2u * 65u + 1u;	/* first flush of the first row count's swap */
	CHECK(11, fenykl_fnfunc_install(&func) == FENYKL_FNFUNC_ESTOCK);
	sim.watch = false;
	sim.corrupt_at = 0;
	CHECK(12, rd32(ROW(0) + 16u) == 0x30 && sim.window_bad == 0);
	wr32(ROW(0) + 16u, CELLS_N);
	CHECK(13, sim_is_stock());
}

static void check_install(void)
{
	const char *text = NULL;
	uint32_t kind;
	bool ok = true;

	sim.watch = true;
	sim.flushes = 0;
	sim.yields = 0;
	sim.window_bad = 0;
	CHECK(20, fenykl_fnfunc_install(&func) == 0);
	sim.watch = false;
	CHECK(21, sim.flushes == 2 * WORDS && sim.window_bad == 0 && sim.yields == 4);
	CHECK(22, fenykl_fnfunc_install(&func) == FENYKL_FNFUNC_EBUSY);
	/* the lists: the stock values, then 0x3BF, served uncached; the four 28-lists share a copy */
	for (unsigned int i = 0; i < FENYKL_FNFUNC_BUTTONS; i++) {
		const struct sim_button *b = &sim_buttons[i];
		const struct sim_region *r = NULL;

		ok = ok && rec_count(b->rec) == b->n + 1 && rec_value(b->rec, b->n) == ID &&
		     (rd32(b->rec + 4u) & 0xF0000000u) == 0xA0000000u;
		for (unsigned int j = 0; j < sim_image_n; j++)
			if (sim_image[j].addr <= b->rec && b->rec < sim_image[j].addr + sim_image[j].len)
				r = &sim_image[j];
		/* the stock list pointer, from the image bytes of the record */
		if (!r)
			ok = false;
		for (unsigned int k = 0; r && k < b->n; k++) {
			const uint8_t *p = r->bytes + (b->rec - r->addr) + 4u;
			uint32_t list = p[0] | p[1] << 8 | (uint32_t)p[2] << 16 | (uint32_t)p[3] << 24;

			ok = ok && rec_value(b->rec, k) == rd16(list + 2u * k);
		}
	}
	CHECK(23, ok && rd32(FW_SETTING_REC_FN1 + 4u) == rd32(FW_SETTING_REC_FN3 + 4u) &&
		  rd32(FW_SETTING_REC_FN1 + 4u) != rd32(FW_SETTING_REC_LFN + 4u) &&
		  rec_value(FW_SETTING_REC_LFN, 0) == 0x7D9);
	/* every selector key: name and help of 0x3BF, stock labels kept */
	for (unsigned int k = 0; k < KEYS; k++) {
		kind = fw_selector(k, false, ID, &text);
		ok = ok && sim_text(kind, text, name);
		kind = fw_selector(k, true, ID, &text);
		ok = ok && sim_text(kind, text, help);
		ok = ok && fw_selector(k, false, OFF, &text) == 4 &&
		     fw_selector(k, true, 0x306, &text) == 4;
	}
	CHECK(24, ok);
	/* the five button rows show the name; the arrow rows stay stock */
	for (unsigned int i = 0; i < FENYKL_FNFUNC_BUTTONS; i++) {
		kind = fw_cell(sim_buttons[i].row, ID, &text);
		ok = ok && sim_text(kind, text, name) && fw_cell(sim_buttons[i].row, 0x306, &text) == 3;
	}
	CHECK(25, ok && rd32(ROW(4) + 12u) == FW_BUTTON_CELLS && rd32(ROW(5) + 16u) == CELLS_N &&
		  !fw_cell(4, ID, &text));
	/* the stock tables themselves are untouched */
	CHECK(26, !memcmp((const void *)FW_FUNC_NAMES, (const void *)rd32(FW_FUNC_SELECTOR_KEYS + 12u),
			  12u * NAMES_N));
}

static void check_press(void)
{
	/* no button holds the entry: no hook */
	CHECK(30, fenykl_fnfunc_tick() == 0 && !fenykl_hook_appevent_post.installed);
	sim.buttons[2] = ID;
	CHECK(31, fenykl_fnfunc_tick() == 0 && fenykl_hook_appevent_post.installed);
	CHECK(32, pressed(PRESS(0x1209), FENYKL_FNFUNC_FN2) && pressed(RELEASE(0x1209), -1));
	/* Fn1 holds magnify; a non-key event; Fn2 under setting 0x217 = 3 (no override) and 5 */
	CHECK(33, pressed(PRESS(0x000B), -1) && pressed(0x04030020u, -1));
	sim.mode = 3;
	CHECK(34, pressed(PRESS(0x1209), FENYKL_FNFUNC_FN2));
	sim.mode = 5;
	CHECK(35, pressed(PRESS(0x1209), -1));
	sim.buttons[1] = ID;
	CHECK(36, pressed(PRESS(0x120A), -1));
	sim.mode = 3;
	CHECK(37, pressed(PRESS(0x120A), -1));
	sim.mode = 1;
	CHECK(38, pressed(PRESS(0x120A), FENYKL_FNFUNC_REC));
	sim.buttons[0] = ID;
	sim.buttons[4] = ID;
	sim.lfn = ID;
	sim.mode = 6;
	CHECK(39, pressed(PRESS(0x000B), FENYKL_FNFUNC_FN1) &&
		  pressed(PRESS(0x1224), FENYKL_FNFUNC_FN3) &&
		  pressed(PRESS(0x2202), FENYKL_FNFUNC_LFN));
	CHECK(40, fenykl_fnfunc_tick() == 0);
}

void plugin_main(uint32_t load_base, uint32_t image_size)
{
	(void)load_base;
	(void)image_size;
	check_refusals();
	check_install();
	check_press();
	sim_exit_code = sim.first_fail;
}
